#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
MFP-3 ONE FILE v1.10 — EVENT CAUSAL ENGINE
===========================================

Un único archivo que ejecuta v1.9.1 y añade:

- clustering de titulares en EVENTOS reales;
- conteo de fuentes independientes;
- penalización por duplicación;
- detección básica de "actual vs expected";
- régimen de mercado asociado al evento;
- outcomes por evento (no por titular repetido);
- memoria causal categoría -> activo -> horizonte;
- causal pressure actual del Challenger;
- diversidad mínima de fuentes;
- health/backup heredados de v1.9.1.

No modifica v1.7-FROZEN.
No ejecuta operaciones reales.

Uso:
    py mfp3_onefile_v1_10.py
    py mfp3_onefile_v1_10.py --install
    py mfp3_onefile_v1_10.py --uninstall
    py mfp3_onefile_v1_10.py --health
    py mfp3_onefile_v1_10.py --status
    py mfp3_onefile_v1_10.py --full
"""

from __future__ import annotations

import argparse
import base64
import json
import math
import re
import sys
import zlib
from datetime import datetime, timezone
from pathlib import Path
from typing import Dict, List, Tuple

import numpy as np
import pandas as pd

V191_B64 = """"""

def embedded_source(blob: str) -> str:
    return zlib.decompress(base64.b64decode(blob)).decode("utf-8")

V191_SOURCE = embedded_source(V191_B64)

ROOT = Path(".")
EVENT_DIR = ROOT / "mfp3_event_intelligence"
MASTER = ROOT / "mfp3_master"

ENRICHED = EVENT_DIR / "events_enriched.csv"
OUTCOMES = EVENT_DIR / "event_outcomes.csv"
CONTEXT = EVENT_DIR / "market_context.csv"

CLUSTERS = EVENT_DIR / "event_clusters.csv"
CLUSTER_MEMBERS = EVENT_DIR / "event_cluster_members.csv"
CLUSTER_OUTCOMES = EVENT_DIR / "event_cluster_outcomes.csv"
CAUSAL_MEMORY = EVENT_DIR / "causal_memory.csv"
CURRENT_CAUSAL = EVENT_DIR / "current_causal_pressure.csv"
SURPRISES = EVENT_DIR / "surprise_events.csv"
CAUSAL_REPORT = MASTER / "causal_daily_report.csv"

# ---------------------------------------------------------------------
# TOKEN / SOURCE HELPERS
# ---------------------------------------------------------------------

STOP = {
    "the","and","for","with","from","that","this","into","after","before",
    "over","under","amid","says","say","new","news","market","markets",
    "stock","stocks","price","prices","latest","update","report",
}

def now_utc():
    return datetime.now(timezone.utc).isoformat(timespec="seconds")

def toks(text: str) -> set:
    ws = re.findall(r"[a-zA-Z0-9]{3,}", (text or "").lower())
    return {w for w in ws if w not in STOP}

def jaccard(a: set, b: set) -> float:
    if not a or not b:
        return 0.0
    u = len(a | b)
    return len(a & b) / u if u else 0.0

def norm_source(x: str) -> str:
    x = (x or "").strip().lower()
    x = re.sub(r"\s+", " ", x)
    return x[:120]

def parse_ts(x):
    return pd.to_datetime(x, errors="coerce", utc=True)

# ---------------------------------------------------------------------
# BASIC SURPRISE PARSER
# ---------------------------------------------------------------------

NUM = r"([-+]?\d+(?:\.\d+)?)\s*(%|percent|bp|bps|basis points|pp)?"

PATTERNS = [
    re.compile(
        rf"(?:actual|came in at|rose to|fell to)\s*{NUM}.*?"
        rf"(?:expected|forecast|consensus)\s*{NUM}",
        re.I,
    ),
    re.compile(
        rf"{NUM}\s*(?:vs|versus)\s*{NUM}\s*"
        rf"(?:expected|forecast|consensus)?",
        re.I,
    ),
]

def unit_factor(unit: str | None) -> float:
    u = (unit or "").lower()
    if u in {"bp","bps","basis points"}:
        return 0.01
    return 1.0

def parse_surprise(title: str) -> dict:
    text = title or ""

    for p in PATTERNS:
        m = p.search(text)
        if not m:
            continue

        groups = list(m.groups())

        try:
            if len(groups) >= 4:
                a = float(groups[0]) * unit_factor(groups[1])
                e = float(groups[2]) * unit_factor(groups[3])
            else:
                continue
        except Exception:
            continue

        scale = max(abs(e), 1.0)
        score = (a - e) / scale

        return {
            "surprise_detected": 1,
            "actual_value": a,
            "expected_value": e,
            "surprise_raw": a - e,
            "surprise_score": score,
        }

    return {
        "surprise_detected": 0,
        "actual_value": np.nan,
        "expected_value": np.nan,
        "surprise_raw": np.nan,
        "surprise_score": np.nan,
    }

# ---------------------------------------------------------------------
# MARKET REGIME FROM CONTEXT SNAPSHOTS
# ---------------------------------------------------------------------

def getnum(row, name):
    try:
        v = float(row.get(name))
        return v if np.isfinite(v) else np.nan
    except Exception:
        return np.nan

def regime_from_row(row: dict) -> str:
    vix = getnum(row, "vix_close")
    spy20 = getnum(row, "spy_ret_20")
    qqq20 = getnum(row, "qqq_ret_20")
    copper20 = getnum(row, "hg_f_ret_20")
    usd20 = getnum(row, "uup_ret_20")
    clp20 = getnum(row, "clp_x_ret_20")

    risk = "NEUTRAL"
    if np.isfinite(vix) and vix >= 25:
        risk = "RISK_OFF"
    elif (np.isfinite(spy20) and spy20 <= -0.06) or (
        np.isfinite(qqq20) and qqq20 <= -0.08
    ):
        risk = "RISK_OFF"
    elif (
        np.isfinite(vix) and vix < 18
        and np.isfinite(spy20) and spy20 > 0.02
    ):
        risk = "RISK_ON"

    copper = "COPPER_NEUTRAL"
    if np.isfinite(copper20):
        if copper20 >= 0.06:
            copper = "COPPER_STRONG"
        elif copper20 <= -0.06:
            copper = "COPPER_WEAK"

    usd = "USD_NEUTRAL"
    if np.isfinite(usd20):
        if usd20 >= 0.025:
            usd = "USD_STRONG"
        elif usd20 <= -0.025:
            usd = "USD_WEAK"

    clp = "CLP_NEUTRAL"
    if np.isfinite(clp20):
        if clp20 >= 0.03:
            clp = "CLP_WEAK"
        elif clp20 <= -0.03:
            clp = "CLP_STRONG"

    return f"{risk}|{copper}|{usd}|{clp}"

def load_context():
    if not CONTEXT.exists():
        return pd.DataFrame()
    try:
        c = pd.read_csv(CONTEXT)
    except Exception:
        return pd.DataFrame()

    if c.empty or "recorded_at_utc" not in c:
        return pd.DataFrame()

    c["ctx_ts"] = pd.to_datetime(
        c["recorded_at_utc"], errors="coerce", utc=True
    )
    c = c.dropna(subset=["ctx_ts"]).sort_values("ctx_ts")
    c["regime"] = [
        regime_from_row(r._asdict())
        for r in c.itertuples(index=False)
    ]
    return c

def nearest_regime(ts, context: pd.DataFrame):
    if context.empty or pd.isna(ts):
        return "UNKNOWN"

    past = context[context["ctx_ts"] <= ts]
    if past.empty:
        return "UNKNOWN"
    return str(past.iloc[-1]["regime"])

# ---------------------------------------------------------------------
# CLUSTERING
# ---------------------------------------------------------------------

def cluster_events() -> Tuple[pd.DataFrame, pd.DataFrame]:
    if not ENRICHED.exists():
        return pd.DataFrame(), pd.DataFrame()

    try:
        df = pd.read_csv(ENRICHED)
    except Exception:
        return pd.DataFrame(), pd.DataFrame()

    if df.empty:
        return pd.DataFrame(), pd.DataFrame()

    df["retrieved_ts"] = pd.to_datetime(
        df["retrieved_at_utc"], errors="coerce", utc=True
    )
    df = df.dropna(subset=["retrieved_ts"]).sort_values("retrieved_ts")

    context = load_context()

    clusters = []
    members = []

    # state: clusters recientes con tokens representativos
    active = []

    for row in df.itertuples(index=False):
        title = str(getattr(row, "title", ""))
        category = str(getattr(row, "category", "UNKNOWN"))
        tag = str(getattr(row, "asset_tag", "GLOBAL"))
        ts = getattr(row, "retrieved_ts")
        tt = toks(title)

        best_i = None
        best_sim = 0.0

        # Sólo comparar con eventos de la misma categoría en ±72h.
        for i, c in enumerate(active):
            if c["category"] != category:
                continue

            age_h = abs((ts - c["last_ts"]).total_seconds()) / 3600.0
            if age_h > 72:
                continue

            sim = jaccard(tt, c["token_union"])
            if sim > best_sim:
                best_i = i
                best_sim = sim

        if best_i is not None and best_sim >= 0.30:
            c = active[best_i]
            c["last_ts"] = ts
            c["token_union"] |= tt
            c["headline_count"] += 1
            c["sources"].add(norm_source(getattr(row, "source", "")))
            c["event_ids"].append(str(getattr(row, "event_id", "")))
            c["sentiments"].append(
                float(getattr(row, "lexical_sentiment", 0.0) or 0.0)
            )
            c["novelties"].append(
                float(getattr(row, "novelty_score", 0.0) or 0.0)
            )
            c["intensities"].append(
                float(getattr(row, "event_intensity", 0.0) or 0.0)
            )
            cid = c["cluster_id"]

        else:
            cid = f"EC{len(clusters)+len(active)+1:06d}"
            c = {
                "cluster_id": cid,
                "category": category,
                "asset_tag": tag,
                "first_ts": ts,
                "last_ts": ts,
                "representative_title": title,
                "representative_event_id": str(getattr(row, "event_id", "")),
                "token_union": set(tt),
                "headline_count": 1,
                "sources": {norm_source(getattr(row, "source", ""))},
                "event_ids": [str(getattr(row, "event_id", ""))],
                "sentiments": [
                    float(getattr(row, "lexical_sentiment", 0.0) or 0.0)
                ],
                "novelties": [
                    float(getattr(row, "novelty_score", 0.0) or 0.0)
                ],
                "intensities": [
                    float(getattr(row, "event_intensity", 0.0) or 0.0)
                ],
            }
            active.append(c)

        members.append({
            "event_id": str(getattr(row, "event_id", "")),
            "cluster_id": cid,
            "similarity_to_cluster": best_sim if best_i is not None else 1.0,
        })

    # Convert active clusters to final output.
    final = []
    for c in active:
        unique_sources = len([s for s in c["sources"] if s])
        headlines = c["headline_count"]

        # Diversity/source confirmation increases with independent sources,
        # but repetition alone is penalized.
        confirmation = 1.0 - math.exp(-unique_sources / 3.0)
        duplication_penalty = unique_sources / max(headlines, 1)
        duplication_penalty = min(1.0, math.sqrt(duplication_penalty))

        novelty = float(np.mean(c["novelties"])) if c["novelties"] else 0.0
        intensity = float(np.mean(c["intensities"])) if c["intensities"] else 0.0
        sentiment = float(np.mean(c["sentiments"])) if c["sentiments"] else 0.0

        causal_strength = (
            confirmation
            * duplication_penalty
            * (0.5 + 0.5 * novelty)
            * (0.5 + 0.5 * min(intensity, 2.0))
        )

        surprise = parse_surprise(c["representative_title"])
        regime = nearest_regime(c["first_ts"], context)

        final.append({
            "cluster_id": c["cluster_id"],
            "category": c["category"],
            "asset_tag": c["asset_tag"],
            "first_observed_utc": c["first_ts"].isoformat(),
            "last_observed_utc": c["last_ts"].isoformat(),
            "representative_event_id": c["representative_event_id"],
            "representative_title": c["representative_title"],
            "headline_count": headlines,
            "independent_sources": unique_sources,
            "confirmation_score": confirmation,
            "duplication_penalty": duplication_penalty,
            "mean_sentiment": sentiment,
            "mean_novelty": novelty,
            "mean_intensity": intensity,
            "causal_strength": causal_strength,
            "regime": regime,
            **surprise,
        })

    cdf = pd.DataFrame(final)
    mdf = pd.DataFrame(members)

    cdf.to_csv(CLUSTERS, index=False, encoding="utf-8-sig")
    mdf.to_csv(CLUSTER_MEMBERS, index=False, encoding="utf-8-sig")

    if len(cdf):
        cdf[cdf["surprise_detected"] == 1].to_csv(
            SURPRISES,
            index=False,
            encoding="utf-8-sig",
        )
    else:
        pd.DataFrame().to_csv(SURPRISES, index=False)

    return cdf, mdf

# ---------------------------------------------------------------------
# CLUSTER OUTCOMES
# ---------------------------------------------------------------------

def build_cluster_outcomes(
    clusters: pd.DataFrame,
) -> pd.DataFrame:

    if clusters.empty or not OUTCOMES.exists():
        return pd.DataFrame()

    try:
        if OUTCOMES.stat().st_size == 0:
            return pd.DataFrame()
        out = pd.read_csv(OUTCOMES)
    except Exception:
        return pd.DataFrame()

    if out.empty or "event_id" not in out:
        return pd.DataFrame()

    # Sólo el evento representativo del cluster: evita contar 137 titulares
    # del mismo hecho como 137 observaciones independientes.
    left = clusters[
        [
            "cluster_id",
            "representative_event_id",
            "category",
            "asset_tag",
            "independent_sources",
            "causal_strength",
            "regime",
            "mean_sentiment",
            "surprise_detected",
            "surprise_score",
        ]
    ].copy()

    z = left.merge(
        out,
        left_on="representative_event_id",
        right_on="event_id",
        how="left",
    )

    z.to_csv(
        CLUSTER_OUTCOMES,
        index=False,
        encoding="utf-8-sig",
    )
    return z

# ---------------------------------------------------------------------
# CAUSAL MEMORY
# ---------------------------------------------------------------------

def build_causal_memory(
    cluster_outcomes: pd.DataFrame,
) -> pd.DataFrame:

    if cluster_outcomes.empty:
        pd.DataFrame().to_csv(CAUSAL_MEMORY, index=False)
        return pd.DataFrame()

    rows = []

    group_cols = [
        "category",
        "evaluated_asset",
        "regime",
    ]

    for keys, g in cluster_outcomes.groupby(group_cols, dropna=False):
        rec = dict(zip(group_cols, keys))
        rec["n_clusters"] = len(g)
        rec["mean_sources"] = float(
            pd.to_numeric(
                g["independent_sources"], errors="coerce"
            ).mean()
        )
        rec["mean_causal_strength"] = float(
            pd.to_numeric(
                g["causal_strength"], errors="coerce"
            ).mean()
        )

        for h in [1, 5, 20]:
            valid = g[
                pd.to_numeric(
                    g.get(f"matured_{h}s", 0),
                    errors="coerce",
                ).fillna(0) == 1
            ].copy()

            r = pd.to_numeric(
                valid.get(f"ret_{h}s"),
                errors="coerce",
            ).dropna()

            n = len(r)
            rec[f"n_{h}s"] = n

            if n:
                mean = float(r.mean())
                med = float(r.median())
                hit = float((r > 0).mean())

                # Empirical-Bayes-style shrinkage hacia cero.
                weight = n / (n + 20.0)
                shrunk = mean * weight

                rec[f"mean_ret_{h}s"] = mean
                rec[f"median_ret_{h}s"] = med
                rec[f"positive_rate_{h}s"] = hit
                rec[f"shrunk_mean_ret_{h}s"] = shrunk
            else:
                rec[f"mean_ret_{h}s"] = np.nan
                rec[f"median_ret_{h}s"] = np.nan
                rec[f"positive_rate_{h}s"] = np.nan
                rec[f"shrunk_mean_ret_{h}s"] = 0.0

        rows.append(rec)

    mem = pd.DataFrame(rows)
    mem.to_csv(
        CAUSAL_MEMORY,
        index=False,
        encoding="utf-8-sig",
    )
    return mem

# ---------------------------------------------------------------------
# CURRENT CAUSAL PRESSURE
# ---------------------------------------------------------------------

def current_causal_pressure(
    clusters: pd.DataFrame,
    memory: pd.DataFrame,
) -> pd.DataFrame:

    if clusters.empty:
        return pd.DataFrame()

    c = clusters.copy()
    c["first_ts"] = pd.to_datetime(
        c["first_observed_utc"],
        errors="coerce",
        utc=True,
    )

    cutoff = pd.Timestamp.now(tz="UTC") - pd.Timedelta(hours=48)
    c = c[c["first_ts"] >= cutoff].copy()

    if c.empty:
        return pd.DataFrame()

    now = pd.Timestamp.now(tz="UTC")
    age_h = (
        now - c["first_ts"]
    ).dt.total_seconds() / 3600.0

    c["decay"] = np.exp(-age_h / 24.0)

    rows = []

    for asset in ["QQQ", "ECH", "CPER"]:
        for h in [1, 5, 20]:
            total = 0.0
            used = 0

            for r in c.itertuples(index=False):
                historical_edge = 0.0
                n = 0

                if not memory.empty:
                    m = memory[
                        (memory["category"] == r.category)
                        & (memory["evaluated_asset"] == asset)
                        & (memory["regime"] == r.regime)
                    ]

                    if len(m):
                        historical_edge = float(
                            m.iloc[-1].get(
                                f"shrunk_mean_ret_{h}s",
                                0.0,
                            )
                            or 0.0
                        )
                        n = int(
                            m.iloc[-1].get(
                                f"n_{h}s",
                                0,
                            )
                            or 0
                        )

                # No permitir inferencia fuerte con muestra pequeña.
                maturity_gate = min(1.0, n / 20.0)

                sentiment_direction = np.sign(
                    float(r.mean_sentiment)
                )

                surprise_term = 0.0
                if int(r.surprise_detected) == 1:
                    try:
                        surprise_term = float(r.surprise_score)
                    except Exception:
                        surprise_term = 0.0

                # Score Challenger. No mueve la v1.7.
                score = (
                    float(r.causal_strength)
                    * float(r.decay)
                    * (
                        historical_edge * maturity_gate
                        + 0.0025 * sentiment_direction
                        + 0.0010 * np.tanh(surprise_term)
                    )
                )

                total += score
                used += 1

            rows.append({
                "asset": asset,
                "horizon_sessions": h,
                "causal_pressure": total,
                "recent_clusters_used": used,
            })

    out = pd.DataFrame(rows)
    out.to_csv(
        CURRENT_CAUSAL,
        index=False,
        encoding="utf-8-sig",
    )
    return out

# ---------------------------------------------------------------------
# REPORT
# ---------------------------------------------------------------------

def append_causal_report(
    clusters,
    memory,
    pressure,
):
    MASTER.mkdir(exist_ok=True)

    row = {
        "recorded_at_utc": now_utc(),
        "clusters_total": len(clusters),
        "causal_memory_groups": len(memory),
        "surprise_events_total": (
            int(clusters["surprise_detected"].sum())
            if len(clusters) else 0
        ),
        "mean_independent_sources": (
            float(clusters["independent_sources"].mean())
            if len(clusters) else 0.0
        ),
        "mean_headlines_per_cluster": (
            float(clusters["headline_count"].mean())
            if len(clusters) else 0.0
        ),
    }

    if not pressure.empty:
        for asset in ["QQQ", "ECH", "CPER"]:
            for h in [1, 5, 20]:
                z = pressure[
                    (pressure["asset"] == asset)
                    & (pressure["horizon_sessions"] == h)
                ]
                if len(z):
                    row[f"pressure_{asset.lower()}_{h}s"] = float(
                        z.iloc[-1]["causal_pressure"]
                    )

    path = CAUSAL_REPORT

    if path.exists():
        old = pd.read_csv(path)
        new = pd.concat(
            [old, pd.DataFrame([row])],
            ignore_index=True,
            sort=False,
        )
    else:
        new = pd.DataFrame([row])

    new.to_csv(
        path,
        index=False,
        encoding="utf-8-sig",
    )

# ---------------------------------------------------------------------
# RUN v1.9.1
# ---------------------------------------------------------------------

def run_v191(args):
    old_argv = sys.argv[:]

    try:
        sys.argv = ["mfp3_onefile_v1_9_1_embedded.py"]

        for flag in [
            "--install",
            "--uninstall",
            "--health",
            "--status",
            "--full",
        ]:
            if getattr(args, flag[2:].replace("-", "_"), False):
                sys.argv.append(flag)

        g = {
            "__name__": "mfp3_v191_embedded",
            "__file__": "<embedded:v1.9.1>",
            "__builtins__": __builtins__,
        }

        exec(
            compile(V191_SOURCE, g["__file__"], "exec"),
            g,
            g,
        )
        g["main"]()

    finally:
        sys.argv = old_argv

# ---------------------------------------------------------------------
# MAIN
# ---------------------------------------------------------------------

def main():
    p = argparse.ArgumentParser()
    p.add_argument("--install", action="store_true")
    p.add_argument("--uninstall", action="store_true")
    p.add_argument("--health", action="store_true")
    p.add_argument("--status", action="store_true")
    p.add_argument("--full", action="store_true")
    args = p.parse_args()

    # Modos administrativos se delegan y terminan.
    if args.install or args.uninstall or args.health or args.status:
        run_v191(args)
        return

    print("\n" + "=" * 94)
    print("MFP-3 ONE FILE v1.10 — EVENT CAUSAL ENGINE")
    print("=" * 94)

    run_v191(args)

    print("\n[v1.10] Agrupando titulares en eventos causales...")
    clusters, members = cluster_events()

    print("[v1.10] Construyendo outcomes por evento...")
    co = build_cluster_outcomes(clusters)

    print("[v1.10] Actualizando memoria causal...")
    mem = build_causal_memory(co)

    print("[v1.10] Calculando causal pressure actual...")
    pressure = current_causal_pressure(clusters, mem)

    append_causal_report(clusters, mem, pressure)

    print("\n" + "=" * 94)
    print("RESUMEN CAUSAL v1.10")
    print("=" * 94)

    print("Titulares enriquecidos :", len(members))
    print("Eventos causales únicos :", len(clusters))

    if len(clusters):
        print(
            "Fuentes/evento promedio:",
            f"{clusters['independent_sources'].mean():.2f}"
        )
        print(
            "Titulares/evento promedio:",
            f"{clusters['headline_count'].mean():.2f}"
        )
        print(
            "Eventos con sorpresa detectada:",
            int(clusters["surprise_detected"].sum())
        )

    print("Grupos memoria causal   :", len(mem))

    if not pressure.empty:
        print("\nCausal pressure Challenger:")
        with pd.option_context(
            "display.max_rows", 30,
            "display.max_columns", None,
            "display.width", 170,
        ):
            print(pressure)

    print("\nArchivos nuevos:")
    print(" ", CLUSTERS.resolve())
    print(" ", CLUSTER_OUTCOMES.resolve())
    print(" ", CAUSAL_MEMORY.resolve())
    print(" ", CURRENT_CAUSAL.resolve())

    print(
        "\nIMPORTANTE: causal pressure todavía pertenece al Challenger. "
        "No modifica v1.7-FROZEN hasta demostrar mejora fuera de muestra."
    )

if __name__ == "__main__":
    main()
